import re
LOG = ['  OmniCore Host - CLI hardware tests', '  och.exe : ...\\OmniCoreHost\\build\\och.exe', '  output  : ...', '  groups  : basic, control, args, capture, playback, bench, output   bench: 5 s   TX attenuation: 60 dB', '', '  Test conditions', '  os              Microsoft Windows 11 家庭版 中文版 25H2 (build 26200.9711, 64 位)', '  computer        LENOVO ThinkPad E14 Gen 7 (21SXA000CD)', '  memory          32 GiB (2 x 16 GiB DDR5-5600)', '  power_source    AC', '  cpu             Intel(R) Core(TM) Ultra 7 255H (16 cores / 16 threads)', '  power_plan      平衡', '  powershell      5.1.26100.9711', '  usb_driver      libusbK 3.1.0.0', '  usb_controller  Intel(R) USB 3.20 可扩展主机控制器 - 1.20 (Microsoft)', '  capture_disk    UMIS RPJYJ1T24MML1AWQ (SSD, NVMe)', '  device          OmniCoreSDR OMINICORE00000001, firmware SDK_CMD_1.0_20261024_IQ8, USB link 5000 Mbit/s', '', '  PASS  basic     version reports version and ABI 1  - version 0.4.2', '  PASS  basic     find lists the board  - 1 device(s), using OMINICORE00000001', '  PASS  basic     info reports SuperSpeed link and firmware  - SDK_CMD_1.0_20261024_IQ8, USB 5000 Mbit/s', '  PASS  basic     system.status reports initialised RF', '  PASS  basic     commands catalog is valid JSON', '  PASS  basic     clock status has matching RX/TX sample rates  - Fs 61.440 MSPS', '  PASS  basic     FIR status is a verified snapshot', '  PASS  basic     Zynq core temperature is valid and plausible  - 64.483 C', '  PASS  basic     digital loopback self-test', '  PASS  control   rx.lo-frequency set/get round trip  - restored 1000000000 Hz', '  PASS  control   tx1.attenuation set/get round trip  - restored 60 dB', '  PASS  control   config applies RF settings without starting TX', '  PASS  args      exit 2: unknown option  - unknown option --bogus', '  PASS  args      exit 2: bench needs a direction  - bench needs --rx, --tx or both', '  PASS  args      exit 2: rx needs --file  - rx requires --file PATH; use bench --rx to discard samples', '  PASS  args      exit 2: bench rejects --file  - bench does not write/read files; use rx or tx', '  PASS  args      exit 2: unknown canonical command  - unknown canonical command: nonsense.key; use och commands', '  PASS  args      exit 2: invalid number suffix  - invalid numeric suffix/value: 30.72X', '  PASS  args      exit 2: invalid channel list  - channels must be 1, 2 or 1,2', '  PASS  args      exit 2: sc8 requires 8-bit wire  - sc8 requires --iq-bits 8', '  PASS  args      exit 2: 8-bit wire requires duplex  - 8-bit USB IQ requires both RX/TX channel masks=3', '  PASS  args      exit 2: block must be a multiple of 49152  - block must be a multiple of 49152, at most 1048576', '  PASS  args      exit 2: conflicting alias and option  - duplicate or conflicting option --sample-rate', '  PASS  args      exit 2: --loop requires a file  - --loop requires a TX file', '  PASS  args      text-mode error is readable', '  PASS  capture   RX sc16 two-channel capture with metadata  - 121.7 MiB, 15,947,092 samples/ch, 4 boundary record(s)', '  PASS  capture   RX fc32 single-channel capture is normalised  - 64.5 MiB, 8,448,682 samples/ch, 1 boundary record(s)', '  PASS  capture   RX packed12 capture on channel 2  - 23.8 MiB, 8,317,610 samples/ch, 1 boundary record(s)', '  PASS  capture   existing capture is protected without --overwrite', '  PASS  playback  TX plays an sc16 capture to EOF  - 15,947,092 samples/ch in 1.17 s, padding 2732, tail underflow at EOF', '  PASS  playback  TX loops a file for a fixed duration  - 3.7x file length', '  PASS  playback  TX generated 1 MHz tone', '  PASS  playback  TX refuses a file shorter than the prefill', '  PASS  bench     RX 2ch @ 61.44 MSPS (12-bit)  - RX 367.2 MB/s (99.6%)', '  PASS  bench     RX 1ch @ 61.44 MSPS (12-bit)  - RX 183.6 MB/s (99.6%)', '  PASS  bench     TX 2ch @ 61.44 MSPS (12-bit)  - TX 362.0 MB/s (98.2%)', '  WARN  bench     RX+TX 2ch @ 30.72 MSPS (12-bit)  - rx overflow=1 underflow=0 starvation=0; tx overflow=1 underflow=0 starvation=0 RX 183.4 MB/s (99.5%), TX 180.9 MB/s (98.1%)', '  PASS  bench     RX+TX 1ch @ 61.44 MSPS (12-bit)  - RX 183.8 MB/s (99.7%), TX 180.7 MB/s (98.1%)', '  PASS  bench     RX+TX 2ch @ 50 MSPS (8-bit wire)  - RX 199.2 MB/s (99.6%), TX 196.3 MB/s (98.1%)', '  PASS  output    redirected info/status/help are plain ASCII within 78 columns', '  PASS  output    redirected bench prints summary and throughput table', '  PASS  output    --json output carries no text decoration', '', '  Throughput', '', 'Test               Dir Channels  MSPS Seconds  MBps Expected Ratio Overflows Underflows HostDrops TransferErrors', '----               --- --------  ---- -------  ---- -------- ----- --------- ---------- --------- --------------', 'RX 2ch 61.44M      RX         2 61.44    5.08 367.2    368.6  99.6         0          0         0              0', 'RX 1ch 61.44M      RX         1 61.44    5.04 183.6    184.3  99.6         0          0         0              0', 'TX 2ch 61.44M      TX         2 61.44    5.12 362.0    368.6  98.2         0          0         0              0', 'Duplex 2ch 30.72M  RX         2 30.72    5.18 183.4    184.3  99.5         1          0         0              0', 'Duplex 2ch 30.72M  TX         2 30.72    5.13 180.9    184.3  98.1         1          0         0              0', 'Duplex 1ch 61.44M  RX         1 61.44    5.15 183.8    184.3  99.7         0          0         0              0', 'Duplex 1ch 61.44M  TX         1 61.44    5.12 180.7    184.3  98.1         0          0         0              0', 'Duplex 2ch 50M IQ8 RX         2    50    5.17 199.2      200  99.6         0          0         0              0', 'Duplex 2ch 50M IQ8 TX         2    50    5.13 196.3      200  98.1         0          0         0              0', '', '  42 tests: 41 passed, 1 warnings, 0 failed, 0 skipped', '  Report: ...\\cli-hardware-report.json']
G, Y, R0, C, D, Z = '\x1b[92m', '\x1b[93m', '\x1b[91m', '\x1b[96m', '\x1b[90m', '\x1b[0m'
STATUS = {'PASS': G, 'WARN': Y, 'FAIL': R0, 'SKIP': D}
out = ['PS ...\\OmniCoreHost> .\\tests\\hardware\\cli_hardware_tests.ps1', '']
for line in LOG:
    m = re.match(r'^  (PASS|WARN|FAIL|SKIP)  (.*?)(  - .*)?$', line)
    if m:
        out.append(f'  {STATUS[m.group(1)]}{m.group(1)} {Z} {m.group(2)}' + (f'{D}{m.group(3)}{Z}' if m.group(3) else ''))
    elif line.strip() in ('OmniCore Host - CLI hardware tests', 'Test conditions', 'Throughput'):
        out.append(f'{C}{line}{Z}')
    elif re.match(r'^  \d+ tests:', line):
        colour = R0 if ' 0 failed' not in line else (Y if ' 0 warnings' not in line else G)
        out.append(f'{colour}{line}{Z}')
    else:
        out.append(line)
out += ['', 'PS ...\\OmniCoreHost> ']
open('hwtest.ansi', 'w').write('\n'.join(out))
